import{_ as e,C as n,c as i,o as t,j as r,b as s,a0 as a,a as l,w as h,G as o,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Technisches Training vs. Flow-Training","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/the-zone/technical-vs-flow.md","filePath":"de/education/the-zone/technical-vs-flow.md"}');const c=e({name:"de/education/the-zone/technical-vs-flow.md"},[["render",function(e,u,c,g,f,b){const m=n("Mermaid");return t(),i("div",null,[u[1]||(u[1]=r("h1",{id:"technisches-training-vs-flow-training",tabindex:"-1"},[l("Technisches Training vs. Flow-Training "),r("a",{class:"header-anchor",href:"#technisches-training-vs-flow-training","aria-label":'Permalink to "Technisches Training vs. Flow-Training"'},"​")],-1)),u[2]||(u[2]=r("p",null,"Das Verständnis des Unterschieds zwischen technischem Training und Flow-Training ist für die Entwicklung von Spitzensportlern unerlässlich. Beides ist notwendig, dient aber unterschiedlichen Zwecken und erfordert unterschiedliche Ansätze.",-1)),u[3]||(u[3]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"Das Kernprinzip"),r("p",null,[r("strong",null,"Man kann einen Anfänger nicht wie einen Experten ausbilden"),l(" (ihnen fehlen die neuronalen Verbindungen), und "),r("strong",null,"man kann einen Experten nicht wie einen Anfänger ausbilden"),l(" (ein hohes technisches Volumen führt zu übermäßigem Nachdenken).")])],-1)),(t(),s(d,null,{default:h(()=>[o(m,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BAnf%C3%A4nger%20%3Cbr%2F%3E%2090%20%25%20Technologie%5D%20--%3E%20B%5BDazwischenliegend%20%3Cbr%2F%3E%2070%20%25%20Technologie%5D%0A%20%20%20%20B%20--%3E%20C%5BFortschrittlich%20%3Cbr%2F%3E%2050%20%25%20Technologie%5D%0A%20%20%20%20C%20--%3E%20D%5BExperte%20%3Cbr%2F%3E%2020%20%25%20Technologie%5D%0A%0A%20%20%20%20A2%5B10%20%25%20Mental%5D%20--%3E%20B2%5B30%20%25%20Mental%5D%0A%20%20%20%20B2%20--%3E%20C2%5B50%20%25%20Mental%5D%0A%20%20%20%20C2%20--%3E%20D2%5B80%20%25%20mental%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffcdd2%0A%20%20%20%20style%20B%20fill%3A%23ffccbc%0A%20%20%20%20style%20C%20fill%3A%23fff9c4%0A%20%20%20%20style%20D%20fill%3A%23c8e6c9%0A%20%20%20%20style%20D2%20fill%3A%23a5d6a7%0A"})]),fallback:h(()=>[...u[0]||(u[0]=[l(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=a('<h2 id="zwei-arten-von-schulungen" tabindex="-1">Zwei Arten von Schulungen <a class="header-anchor" href="#zwei-arten-von-schulungen" aria-label="Permalink to &quot;Zwei Arten von Schulungen&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Technische Schulung (Explizites Lernen)</p><p><strong>Schwerpunkt:</strong> Mechanik und Form <strong>Achtung:</strong> Bewusste Körperbewegungen <strong>Methode:</strong> Aufschlüsselung der Fertigkeiten, wiederholtes Üben <strong>Ideal für:</strong> Erlernen neuer Fähigkeiten, Korrektur schlechter Gewohnheiten, Aufbau einer soliden Grundlage</p><p><strong>Beispiel:</strong> Üben Sie Ihren Abwurfpunkt 50 Mal mit Videoanalyse</p></div><div class="info custom-block"><p class="custom-block-title">Flow-Training (Implizites Lernen)</p><p><strong>Fokus:</strong> Ergebnisse, nicht Mechanismen <strong>Achtung:</strong> Das Unterbewusstsein die Kontrolle übernehmen lassen <strong>Methode:</strong> Abwechslungsreiches, spielerisches Üben, Visualisierung <strong>Ideal für:</strong> Wettkampfvorbereitung, Stärkung des Selbstvertrauens, Höchstleistungen</p><p><strong>Beispiel:</strong> Übungsspiele unter Druck, bei denen man sich nur auf die Ziele konzentriert</p></div><h2 id="das-dynamische-inversionsmodell" tabindex="-1">Das dynamische Inversionsmodell <a class="header-anchor" href="#das-dynamische-inversionsmodell" aria-label="Permalink to &quot;Das dynamische Inversionsmodell&quot;">​</a></h2><p>Das richtige Trainingsverhältnis verhält sich umgekehrt proportional zur technischen Kompetenz. Je besser man die Technik beherrscht, desto wichtiger wird mentales Training – nicht weniger.</p><h3 id="_1-anfanger-kognitives-stadium" tabindex="-1">1. Anfänger (Kognitives Stadium) <a class="header-anchor" href="#_1-anfanger-kognitives-stadium" aria-label="Permalink to &quot;1. Anfänger (Kognitives Stadium)&quot;">​</a></h3><ul><li>Man denkt bewusst darüber nach, <em>was</em> man tun soll.</li><li>Die Bewegungen fühlen sich unbeholfen an und erfordern Anstrengung.</li><li>Das Gehirn ist vollständig mit Mechanik durchdrungen.</li><li><strong>Verhältnis:</strong> 90 % Technik / 10 % Mental</li><li><strong>Mentale Ausrichtung:</strong> Genuss, externer Fokus (Ziel fixieren), keine komplexe Visualisierung</li></ul><h3 id="_2-zwischenstufe-assoziationsstufe" tabindex="-1">2. Zwischenstufe (Assoziationsstufe) <a class="header-anchor" href="#_2-zwischenstufe-assoziationsstufe" aria-label="Permalink to &quot;2. Zwischenstufe (Assoziationsstufe)&quot;">​</a></h3><ul><li>Man verfeinert die Fertigkeit mit weniger bewusstem Denken</li><li>Die Bewegungen werden flüssiger, Fehler nehmen ab</li><li>Man beginnt, seine eigenen Fehler zu erkennen.</li><li><strong>Verhältnis:</strong> 70 % Technik / 30 % Mental</li><li><strong>Mentaler Fokus:</strong> Entwicklung Ihrer Vorbereitungsroutine (Pre-Performance Routine, PPR)</li></ul><h3 id="_3-fortgeschritten-schwelle-der-autonomie" tabindex="-1">3. Fortgeschritten (Schwelle der Autonomie) <a class="header-anchor" href="#_3-fortgeschritten-schwelle-der-autonomie" aria-label="Permalink to &quot;3. Fortgeschritten (Schwelle der Autonomie)&quot;">​</a></h3><ul><li>Die Fertigkeit ist weitgehend automatisiert.</li><li>Ihr Selbstbild hinkt oft Ihren körperlichen Fähigkeiten hinterher.</li><li>Das Training konzentriert sich auf die Drucksimulation.</li><li><strong>Verhältnis:</strong> 50 % Technik / 50 % Mental</li><li><strong>Mentaler Fokus:</strong> Visualisierung, Selbstbild, Angstbewältigung</li></ul><h3 id="_4-experte-autonome-phase" tabindex="-1">4. Experte (Autonome Phase) <a class="header-anchor" href="#_4-experte-autonome-phase" aria-label="Permalink to &quot;4. Experte (Autonome Phase)&quot;">​</a></h3><ul><li>Technische Fähigkeiten sind vollständig unbewusst.</li><li>Bewusste Konzentration auf die Mechanik stört die Leistung</li><li>Das Wartungsvolumen ist technisch gesehen alles, was Sie benötigen.</li><li><strong>Verhältnis:</strong> 20 % Technik / 80 % Mental</li><li><strong>Mentale Fokussierung:</strong> Flow-Zustand, Strategie, Beruhigung des Geistes</li></ul><h2 id="die-fortschrittstabelle" tabindex="-1">Die Fortschrittstabelle <a class="header-anchor" href="#die-fortschrittstabelle" aria-label="Permalink to &quot;Die Fortschrittstabelle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ebene</th><th>Technik: Mental</th><th>Primäres Ziel</th></tr></thead><tbody><tr><td>Anfänger</td><td>90 : 10</td><td>Baue die Maschine</td></tr><tr><td>Dazwischenliegend</td><td>70 : 30</td><td>Die Fertigkeit stabilisieren</td></tr><tr><td>Fortschrittlich</td><td>50 : 50</td><td>Vertraue der Maschine</td></tr><tr><td>Experte</td><td>20 : 80</td><td>Leistungsfreiheit</td></tr></tbody></table><h2 id="die-expertenfalle" tabindex="-1">Die Expertenfalle <a class="header-anchor" href="#die-expertenfalle" aria-label="Permalink to &quot;Die Expertenfalle&quot;">​</a></h2><p>Für fortgeschrittene und Expertenspieler ist die Rückkehr zu einem stark technischen Fokus gefährlich.</p><p><strong>Das Problem:</strong> Wenn man eine Fertigkeit automatisiert hat, sie aber während eines Wettkampfs bewusst überwacht, aktiviert man den bewussten Verstand und überlagert das Unterbewusstsein. Dies führt zu Leistungsangst und einem „Versagen in entscheidenden Momenten“.</p><p><strong>Die wissenschaftliche Erklärung:</strong> Der Aufwand, der nötig ist, um eine Fertigkeit zu erhalten, ist deutlich geringer (oft nur ein Drittel bis ein Neuntel) als der Aufwand, der nötig ist, um sie zu erlernen. Experten benötigen nur minimales technisches Training, um ihr Können zu bewahren.</p><p><strong>Beispiel aus der Elite:</strong> Champions wie Philippe Quintais und Dylan Rocher konzentrieren sich stark auf taktische Szenarien und kritische Momente anstatt auf mechanische Übungen.</p><p>Anzeichen dafür, dass du die Technik zu sehr hinterfragst:</p><ul><li>Analyse-Paralyse</li><li>Unbeständige Leistungen trotz guter Technik</li><li>Im Wettkampf schlechtere Ergebnisse als im Training</li><li>Es fühlt sich eher „mechanisch“ als fließend an.</li></ul><h2 id="vergleich-der-trainingsmethoden" tabindex="-1">Vergleich der Trainingsmethoden <a class="header-anchor" href="#vergleich-der-trainingsmethoden" aria-label="Permalink to &quot;Vergleich der Trainingsmethoden&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspekt</th><th>Technische Ausbildung</th><th>Flow-Training</th></tr></thead><tbody><tr><td><strong>Praxisart</strong></td><td>Blockiert (dieselbe Fähigkeit wiederholt)</td><td>Zufällig (unterschiedliche Fähigkeiten)</td></tr><tr><td><strong>Rückmeldung</strong></td><td>Sofort, detailliert</td><td>Verzögert, ergebnisorientiert</td></tr><tr><td><strong>Umfeld</strong></td><td>Kontrolliert, vorhersehbar</td><td>Variabel, spielähnlich</td></tr><tr><td><strong>Psychischer Zustand</strong></td><td>Analytisch, bewusst</td><td>Intuitiv, automatisch</td></tr><tr><td><strong>Beste Zeit</strong></td><td>Nebensaison, Kompetenzaufbau</td><td>Vorwettbewerbs-Wartung</td></tr></tbody></table><h2 id="blockiertes-vs-zufalliges-training" tabindex="-1">Blockiertes vs. zufälliges Training <a class="header-anchor" href="#blockiertes-vs-zufalliges-training" aria-label="Permalink to &quot;Blockiertes vs. zufälliges Training&quot;">​</a></h2><p><strong>Blockiertes Training:</strong> Wiederholen Sie denselben Wurf 20 Mal.</p><ul><li>Fühlt sich produktiv an (man sieht schnelle Verbesserungen)</li><li>Gut geeignet für erste Lernprozesse</li><li>Ungeeignet für die langfristige Speicherung</li></ul><p><strong>Zufälliges Üben:</strong> Variieren Sie Entfernung, Ziel und Wurfart.</p><ul><li>Fühlt sich schwieriger an (mehr Fehler)</li><li>Besser für den Wettbewerbstransfer</li><li>Fördert Anpassungsfähigkeit und Entscheidungsfindung</li></ul><h2 id="praktische-richtlinien" tabindex="-1">Praktische Richtlinien <a class="header-anchor" href="#praktische-richtlinien" aria-label="Permalink to &quot;Praktische Richtlinien&quot;">​</a></h2><h3 id="fur-technische-sitzungen" tabindex="-1">Für technische Sitzungen <a class="header-anchor" href="#fur-technische-sitzungen" aria-label="Permalink to &quot;Für technische Sitzungen&quot;">​</a></h3><ol><li>Konzentriere dich jeweils auf EINEN Aspekt.</li><li>Videoanalyse nutzen</li><li>Hol dir Feedback von einem Trainer oder Trainingspartner.</li><li>Akzeptiere, dass es sich anfangs etwas seltsam anfühlen wird.</li><li>Die Sitzungen sollten kürzer sein (Qualität vor Quantität).</li></ol><h3 id="fur-flow-sitzungen" tabindex="-1">Für Flow-Sitzungen <a class="header-anchor" href="#fur-flow-sitzungen" aria-label="Permalink to &quot;Für Flow-Sitzungen&quot;">​</a></h3><ol><li>Erzeuge spielähnlichen Druck</li><li>Konzentriere dich auf das Ziel, nicht auf deinen Körper.</li><li>Halten Sie Ihre Vorbereitungsroutine konsequent ein.</li><li>Analysieren Sie nicht während der Sitzung</li><li>Vertraue deinem Training</li></ol><h2 id="die-integrationsherausforderung" tabindex="-1">Die Integrationsherausforderung <a class="header-anchor" href="#die-integrationsherausforderung" aria-label="Permalink to &quot;Die Integrationsherausforderung&quot;">​</a></h2><p>Die eigentliche Kunst besteht darin, zu wissen, wann man welchen Modus einsetzt:</p><p><strong>Während eines Wettkampfspiels:</strong></p><ul><li>Technisches Denken: NIEMALS während der Ausführung</li><li>Flow-Modus: IMMER beim Werfen</li></ul><p><strong>Während des Trainings:</strong></p><ul><li>Technische Sitzungen: Geplant, spezifischer Schwerpunkt</li><li>Flow-Sessions: Spielsimulation, Druckübungen</li></ul><h2 id="beispiel-fur-einen-wochentlichen-kontostand" tabindex="-1">Beispiel für einen wöchentlichen Kontostand <a class="header-anchor" href="#beispiel-fur-einen-wochentlichen-kontostand" aria-label="Permalink to &quot;Beispiel für einen wöchentlichen Kontostand&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tag</th><th>Sitzungstyp</th><th>Fokus</th></tr></thead><tbody><tr><td>Montag</td><td>Technisch</td><td>Zielgenauigkeit</td></tr><tr><td>Dienstag</td><td>Technisch</td><td>Schussgenauigkeit</td></tr><tr><td>Mittwoch</td><td>Fließen</td><td>Mentales Training, Visualisierung</td></tr><tr><td>Donnerstag</td><td>Gemischt</td><td>Spielszenarien mit Fokus auf Spielfluss</td></tr><tr><td>Freitag</td><td>Technisch</td><td>Schwächebereich</td></tr><tr><td>Samstag</td><td>Fließen</td><td>Spielablauf, Wettbewerbssimulation</td></tr><tr><td>Sonntag</td><td>Ausruhen</td><td>Erholung, Reflexion</td></tr></tbody></table><h2 id="zusammenfassung-regeln-fur-das-trainingsgleichgewicht" tabindex="-1">Zusammenfassung: Regeln für das Trainingsgleichgewicht <a class="header-anchor" href="#zusammenfassung-regeln-fur-das-trainingsgleichgewicht" aria-label="Permalink to &quot;Zusammenfassung: Regeln für das Trainingsgleichgewicht&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regel Nr. 1: Training dem Niveau anpassen</p><p><strong>Anfänger (90/10):</strong> Bauen Sie die Maschine – konzentrieren Sie sich auf die Technik. <strong>Mittelstufe (70/30):</strong> Fertigkeit stabilisieren – mentale Arbeit hinzufügen <strong>Fortgeschritten (50/50):</strong> Vertrauen Sie der Maschine – halten Sie beides im Gleichgewicht. <strong>Experte (20/80):</strong> Handlungsfreiheit – hauptsächlich mental</p></div><div class="tip custom-block"><p class="custom-block-title">Regel Nr. 2: Blockiertes vs. zufälliges Training</p><p><strong>Blockiertes Üben</strong> (wiederholter Wurf): Gut für den Lernprozess, schlecht für die Behaltensleistung. <strong>Zufälliges Training</strong> (variierende Würfe): Im Training schwieriger, im Wettkampf besser.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel Nr. 3: Die Expertenfalle</p><p><strong>Für Experten:</strong> Hohes technisches Volumen führt zu Überdenken und Sprachlosigkeit. <strong>Lösung:</strong> Minimaler technischer Wartungsaufwand, maximales mentales Training</p></div><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Man kann einen Anfänger nicht wie einen Experten ausbilden (ihm fehlen die neuronalen Verbindungen für geistige Arbeit), und man kann einen Experten nicht wie einen Anfänger ausbilden (ein hohes technisches Pensum führt zu Burnout und übermäßigem Nachdenken).</p></blockquote><p>Der Weg von der Technik zum Flow erfordert eine strategische Umkehrung. Passe dein Training an deine Entwicklungsstufe an.</p>',49))])}]]);export{u as __pageData,c as default};
